#!/usr/bin/env python3
"""Brute-force simple ciphers on esnp{d0c_@yz@gl_mn0j_pm3z3_g0_o00s}
Scoring: count of common English trigrams/words in leetspeak-decoded text."""
import re, itertools

CT_WRAP = "esnp"
CT_BODY = "d0c_@yz@gl_mn0j_pm3z3_g0_o00s"
CT_FULL = CT_WRAP + "{" + CT_BODY + "}"

LEET = str.maketrans({'0':'o','1':'i','3':'e','4':'a','5':'s','7':'t','@':'a','$':'s','!':'i','|':'l','+':'t'})

COMMON = ["the","and","ing","you","that","this","with","have","from","flag","ctf",
          "keep","find","ers","erskeep","keepers","finders","video","hidden",
          "meta","data","pastel","color","frame","secret","inside","never","gonna",
          "give","up","let","down","run","around","desert","out","hurt"]

def leet(s):
    return s.translate(LEET)

def score(s):
    t = leet(s.lower())
    sc = 0
    for w in COMMON:
        if len(w) >= 3:
            sc += t.count(w) * len(w)
    # bigram sanity
    for bg in ["th","he","in","er","an","re","on","at","en","es","nd","ou","ng"]:
        sc += t.count(bg)
    return sc

def caesar(s, k, alpha_only=True, shift_digits=False):
    out = []
    for ch in s:
        if 'a' <= ch <= 'z':
            out.append(chr((ord(ch)-97+k) % 26 + 97))
        elif 'A' <= ch <= 'Z':
            out.append(chr((ord(ch)-65+k) % 26 + 65))
        elif ch.isdigit() and shift_digits:
            out.append(str((int(ch)+k) % 10))
        else:
            out.append(ch)
    return ''.join(out)

results = []

# 1) plain Caesar, letters only
for k in range(26):
    body = caesar(CT_BODY, k)
    results.append((score(body), f"caesar letters-only k={k}", body))

# 2) Caesar shifting letters AND digits
for k in range(26):
    body = caesar(CT_BODY, k, shift_digits=True)
    results.append((score(body), f"caesar letters+digits k={k}", body))

# 3) Atbash
atb = ''.join(chr(219-ord(c)) if 'a'<=c<='z' else (chr(155-ord(c)) if 'A'<=c<='Z' else c) for c in CT_BODY)
results.append((score(atb), "atbash", atb))

# 4) ROT47 (ASCII 33-126)
def rot47(s, k):
    o = []
    for ch in s:
        o.append(chr(33 + ((ord(ch)-33+k) % 94)) if 33 <= ord(ch) <= 126 else ch)
    return ''.join(o)
for k in range(94):
    body = rot47(CT_BODY, k)
    results.append((score(body), f"rot47 k={k}", body))

# 5) Vigenere over letters only, various keys, both directions
KEYS = ["canva","finder","finderskeepers","keepers","video","hidden","metadata",
        "xmp","esnp","flag","ctf","pastel","rectangle","animation","secret",
        "finders","keepersfinders","canvavideo","steganography","stego","base64",
        "finderskeeperskeepers","theflag","key","crypto","mp4","subject","bag"]

def vigenere_dec(s, key, mode="vig", keep_pos=True, alpha_only=True):
    # operate on letters; key advances only on letters if alpha_only else on all chars
    out = []
    ki = 0
    for ch in s:
        if 'a' <= ch <= 'z':
            k = ord(key[ki % len(key)].lower()) - 97
            if mode == "vig":
                p = (ord(ch)-97 - k) % 26
            elif mode == "beau":  # beaufort: k - c
                p = (k - (ord(ch)-97)) % 26
            elif mode == "varbeau":  # variant beaufort: c + k
                p = ((ord(ch)-97) + k) % 26
            out.append(chr(p+97))
            ki += 1
        elif 'A' <= ch <= 'Z':
            k = ord(key[ki % len(key)].lower()) - 97
            if mode == "vig":
                p = (ord(ch)-65 - k) % 26
            elif mode == "beau":
                p = (k - (ord(ch)-65)) % 26
            elif mode == "varbeau":
                p = ((ord(ch)-65) + k) % 26
            out.append(chr(p+65))
            ki += 1
        else:
            out.append(ch)
            if not alpha_only:
                ki += 1
    return ''.join(out)

for key in KEYS:
    for mode in ("vig","beau","varbeau"):
        for ao in (True, False):
            body = vigenere_dec(CT_BODY, key, mode, alpha_only=ao)
            results.append((score(body), f"{'beaufort' if mode=='beau' else ('varbeau' if mode=='varbeau' else 'vigenere')} key={key} alpha_only={ao}", body))

# 6) autokey with key esnp / flag / ctf (ciphertext autokey and plaintext autokey)
def autokey_dec(s, key, mode="ct"):
    out = []
    stream = list(key.lower())
    for ch in s:
        if 'a' <= ch <= 'z':
            k = ord(stream.pop(0)) - 97
            p = (ord(ch)-97 - k) % 26
            out.append(chr(p+97))
            stream.append(chr((ord(ch)-97)+97) if mode=="ct" else chr(p+97))
        else:
            out.append(ch)
    return ''.join(out)

for key in ["esnp","flag","ctf","canva","finder","keepers"]:
    for mode in ("ct","pt"):
        body = autokey_dec(CT_BODY, key, mode)
        results.append((score(body), f"autokey-{mode} key={key}", body))

# 7) wrapper analysis: what k maps flag->esnp / ctf->esnp
print("=== WRAPPER ANALYSIS ===")
for plain in ["flag","ctf"]:
    for k in range(26):
        enc = caesar(plain, k)
        if enc == CT_WRAP:
            print(f"  caesar: {plain} +{k} = esnp  (so body shift = -{k} i.e. decrypt with k={k})")
    # check per-letter deltas
    deltas = [(ord(c)-ord(p)) % 26 for p, c in zip(plain, CT_WRAP)]
    print(f"  {plain}->esnp per-letter deltas (mod26): {deltas}")

print()
print("=== TOP 40 CANDIDATES ===")
results.sort(key=lambda x: -x[0])
for sc, name, body in results[:40]:
    print(f"{sc:4d}  {name:45s}  {body}")
    print(f"      leet-decoded: {leet(body)}")

